# Prepare the 4 files as gzip-base64
python3 << 'PYEOF'
import base64, gzip, json, urllib.request

TOKEN = open("/tmp/owner_token.txt").read().strip()

def gzip_b64(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()
    compressed = gzip.compress(data, compresslevel=9)
    return base64.b64encode(compressed).decode('ascii')

files = [
    {
        "path": "backend/api/ivx-owner-ai.ts",
        "content": gzip_b64("backend/api/ivx-owner-ai.ts"),
        "contentEncoding": "gzip-base64"
    },
    {
        "path": "backend/hono.ts",
        "content": gzip_b64("backend/hono.ts"),
        "contentEncoding": "gzip-base64"
    },
    {
        "path": "expo/app.config.ts",
        "content": gzip_b64("expo/app.config.ts"),
        "contentEncoding": "gzip-base64"
    },
    {
        "path": "expo/android/app/build.gradle",
        "content": gzip_b64("expo/android/app/build.gradle"),
        "contentEncoding": "gzip-base64"
    }
]

payload = {
    "action": "github_commit_multi_file",
    "confirm": True,
    "confirmText": "CONFIRM_IVX_GITHUB_WRITE",
    "input": {
        "commitMessage": "fix(v6.11): approval resume now re-executes deployment pipeline instead of stale property query — V6.11 audit fix",
        "files": files
    }
}

body = json.dumps(payload).encode('utf-8')
req = urllib.request.Request(
    "https://api.ivxholding.com/api/ivx/developer-deploy/action",
    data=body,
    headers={
        "Authorization": f"Bearer {TOKEN}",
        "Content-Type": "application/json"
    },
    method='POST'
)

try:
    with urllib.request.urlopen(req, timeout=60) as resp:
        raw = resp.read().decode('utf-8')
        result = json.loads(raw)
        print(f"HTTP {resp.status}")
        print(f"ok: {result.get('ok')}")
        print(f"commitSha: {result.get('commitSha', result.get('commit_sha', 'none'))}")
        print(f"commitUrl: {result.get('commitUrl', result.get('commit_url', 'none'))}")
        print(f"message: {result.get('message', result.get('error', 'none'))[:300]}")
except urllib.error.HTTPError as e:
    raw = e.read().decode('utf-8')
    print(f"HTTP {e.code}")
    print(f"Error: {raw[:500]}")
except Exception as e:
    print(f"Exception: {str(e)[:300]}")
PYEOF

